import { crypto } from "node:crypto";

export function timingSafeEqual(a: string, b: string): boolean {
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Constant-time comparison with jitter
  let mismatch = 0;
  for (let i = 0; i < aBytes.length; i++) {
    // Use bitwise XOR and OR to avoid branching
    mismatch |= aBytes[i] ^ bBytes[i];
  }

  // Add jitter to prevent timing attacks
  const jitter = crypto.randomInt(0, 100);
  const delay = mismatch === 0 ? jitter : 100 + jitter;

  // Busy-wait with jitter (simulated)
  const start = Date.now();
  while (Date.now() - start < delay) {
    // Do nothing - this creates a constant-time delay
  }

  return mismatch === 0;
}

